#!/usr/bin/env node
/**
 * Ships the customer app's catalogue photos and banners inside the app, so
 * they show instantly, offline, and whether or not the website is deployed
 * with them.
 *
 *   canonical source   assets/web/{areas,services,services/pet,services/helping,banners}
 *   generated copies   mobile/apps/customer/assets/catalog/<same paths>
 *   generated map      mobile/apps/customer/src/lib/bundledArt.generated.ts
 *
 * assets/web stays the one source of truth: never edit the copies or the map.
 * The copies live inside the app because Metro (expo export, and so EAS Build)
 * only resolves files under the Expo server root; requiring
 * assets/web directly works in the dev server but fails the production bundle.
 *
 * The map is keyed by the website path the shared logic already returns
 * ("/areas/vehicles.jpg"), so serviceArt.js and homepageContent.js stay as they
 * are; anything not bundled still loads from the website.
 *
 *   node tools/sync-bundled-art.js           copy changed pictures, remove stale copies, rewrite the map
 *   node tools/sync-bundled-art.js --check   fail if any copy is missing, different or stale, or the map is out of date (CI)
 * (run from mobile/)
 */
const fs = require('fs');
const path = require('path');

const webRoot = path.resolve(__dirname, '../../assets/web');
const appRoot = path.resolve(__dirname, '../apps/customer');
const copyRoot = path.join(appRoot, 'assets/catalog');
const mapFile = path.join(appRoot, 'src/lib/bundledArt.generated.ts');
const FOLDERS = ['areas', 'services', 'services/pet', 'services/helping', 'banners'];
const IMAGE = /\.(jpe?g|png|webp)$/i;
const check = process.argv.includes('--check');

// A missing source folder (partial checkout, wrong directory) must never read as "every copy is stale" and wipe them.
const missingFolders = FOLDERS.filter((folder) => !fs.existsSync(path.join(webRoot, folder)));
if (missingFolders.length) {
  console.error(`Cannot find the canonical artwork: ${missingFolders.map((f) => `assets/web/${f}`).join(', ')}. Nothing was changed.`);
  process.exit(1);
}

/** Every picture to bundle, as a path relative to assets/web ("areas/vehicles.jpg"). */
const pictures = FOLDERS.flatMap((folder) => {
  const dir = path.join(webRoot, folder);
  return fs.readdirSync(dir).filter((f) => IMAGE.test(f) && fs.statSync(path.join(dir, f)).isFile()).sort().map((f) => `${folder}/${f}`);
});
if (!pictures.length) {
  console.error('assets/web has no pictures to bundle. Nothing was changed.');
  process.exit(1);
}

/** Copies already in the app, relative to assets/catalog. */
function existingCopies(dir = copyRoot, prefix = '') {
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap((e) => (e.isDirectory()
    ? existingCopies(path.join(dir, e.name), `${prefix}${e.name}/`)
    : IMAGE.test(e.name) ? [`${prefix}${e.name}`] : []));
}

const relFromMap = path.relative(path.dirname(mapFile), copyRoot).split(path.sep).join('/');
const map = `/**
 * GENERATED by mobile/tools/sync-bundled-art.js from assets/web. Do not edit:
 * change the pictures there, then run \`node tools/sync-bundled-art.js\` from mobile/.
 */
/* eslint-disable */
import type { ImageSourcePropType } from 'react-native';

export const BUNDLED_ART: Record<string, ImageSourcePropType> = {
${pictures.map((p) => `  '/${p}': require('${relFromMap}/${p}'),`).join('\n')}
};
`;

const same = (a, b) => fs.existsSync(b) && fs.readFileSync(a).equals(fs.readFileSync(b));
const wanted = new Set(pictures);
const changed = pictures.filter((p) => !same(path.join(webRoot, p), path.join(copyRoot, p)));
const stale = existingCopies().filter((p) => !wanted.has(p));
const mapStale = !fs.existsSync(mapFile) || fs.readFileSync(mapFile, 'utf8') !== map;

if (check) {
  const problems = [
    ...changed.map((p) => `missing or different copy: assets/catalog/${p}`),
    ...stale.map((p) => `stale copy (no longer in assets/web): assets/catalog/${p}`),
    ...(mapStale ? ['bundledArt.generated.ts is out of date'] : []),
  ];
  if (problems.length) {
    console.error(`Bundled art is out of sync with assets/web:\n  ${problems.join('\n  ')}\nRun: node tools/sync-bundled-art.js (from mobile/)`);
    process.exit(1);
  }
  console.log(`Bundled art in sync: ${pictures.length} pictures.`);
} else {
  for (const p of changed) {
    fs.mkdirSync(path.dirname(path.join(copyRoot, p)), { recursive: true });
    fs.copyFileSync(path.join(webRoot, p), path.join(copyRoot, p));
  }
  for (const p of stale) fs.unlinkSync(path.join(copyRoot, p));
  fs.mkdirSync(path.dirname(mapFile), { recursive: true });
  if (mapStale) fs.writeFileSync(mapFile, map);
  console.log(`${pictures.length} pictures: ${changed.length} copied, ${stale.length} stale removed, map ${mapStale ? 'rewritten' : 'unchanged'}.`);
}
